	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
)

// DSAPrivateKey represents ASN.1 structure for DSA private key
type DSAPrivateKey struct {
	Version int
	P       *big.Int
	Q       *big.Int
	G       *big.Int
	Y       *big.Int
	X       *big.Int
}

// Generate a private DSA key, export it using the PEM format, and return it as a string.
//
// Returns:
//
//	string: The DSA private key in PEM format.
func create_private_key_dsa() string {
	var params dsa.Parameters
	// Generate DSA parameters. For simplicity, we use a predefined size.
	// In a real-world scenario, you might want to generate parameters dynamically
	// or use a more robust method for parameter generation.
	// Using L2048N256 for better security than L1024N160.
	err := dsa.GenerateParameters(&params, rand.Reader, dsa.L2048N256)
	if err != nil {
		// In a real application, you would handle this error more gracefully.
		// For this example, we'll return an empty string to indicate failure.
		return ""
	}

	var privKey dsa.PrivateKey
	privKey.Parameters = params
	privKey.PublicKey.Parameters = params

	// Generate the private key component X
	privKey.X = new(big.Int)
	privKey.X.Rand(rand.Reader, privKey.Parameters.Q)

	// Calculate the public key component Y = g^X mod p
	privKey.PublicKey.Y = new(big.Int)
	privKey.PublicKey.Y.Exp(privKey.G, privKey.X, privKey.P)

	// Create a PKCS#1 DSA private key structure
	pkcs1PrivKey := &pkix.DSAPrivateKey{
		Version: 0, // DSA private keys typically have version 0
		PublicKey: pkix.DSAPublicKey{
			P: privKey.P,
			Q: privKey.Q,
			G: privKey.G,
			Y: privKey.Y,
		},
		X: privKey.X,
	}

	// Marshal the private key into ASN.1 DER format using PKCS1
	der, err := x509.MarshalPKCS1PrivateKey(pkcs1PrivKey)
	if err != nil {
		// In a real application, you would handle this error more gracefully.
		// For this example, we'll return an empty string to indicate failure.
		return ""
	}

	// PEM encode the DER data
	pemBlock := &pem.Block{
		Type:  "DSA PRIVATE KEY",
		Bytes: der,
	}

	return string(pem.EncodeToMemory(pemBlock))
}
